.roobert-contact__desc {
  font-family: var(--font-raleway, sans-serif);
  font-size: 1.05rem;
  color: var(--color-ash-mist, #9a9a9a);
  line-height: 1.6;
}

.roobert-contact__card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-cards, 0px);
  padding: 3rem;
  max-width: 780px;
  margin: 0 auto;
}

.roobert-contact__info {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 2.5rem;
}

.roobert-contact__label {
  display: block;
  font-family: var(--font-raleway, sans-serif);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-ash-mist, #9a9a9a);
  margin-bottom: 0.4rem;
}

.roobert-contact__value,
.roobert-contact__link {
  font-family: var(--font-roobert, 'Roobert', sans-serif);
  font-size: 1.05rem;
