.ro-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  background: var(--surface-obsidian, var(--color-obsidian));
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: background 0.3s, box-shadow 0.3s;
