.ro-header:hover {
  box-shadow: none;
}
.ro-header__inner {
  max-width: var(--page-max-width, 1140px);
  margin: 0 auto;
  padding: 0 var(--spacing-28);
  height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-18);
}
.ro-header__logo {
  font-family: var(--font-roobert, 'Roboto', sans-serif);
  font-size: 1.35rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-paper);
  text-decoration: none;
  letter-spacing: -0.01em;
}
.ro-header__nav {
  display: flex;
  gap: var(--element-gap);
}
.ro-header__link {
  color: #949494;
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: var(--font-weight-regular);
  transition: color 0.2s;
}
.ro-header__link:hover {
  color: var(--color-paper, #ffffff);
}
.ro-header__actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-8);
}
.ro-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1.4rem;
  background: var(--color-iridescent-fade, var(--gradient-iridescent-fade));
  color: var(--color-paper, #ffffff);
  border-radius: var(--radius-buttons);
  font-size: 0.88rem;
  font-weight: var(--font-weight-semibold);
  text-decoration: none;
  transition: opacity 0.2s, transform 0.2s;
}
.ro-header__cta:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}
.ro-header__toggle {
  display: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-direction: column;
  gap: 4px;
}
.ro-header__bar {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-paper, #ffffff);
  border-radius: 0;
}
.ro-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: var(--spacing-28);
  background: var(--surface-obsidian, var(--color-obsidian));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: var(--spacing-14);
  padding-bottom: var(--spacing-28);
}
.ro-header__mobile-link {
  color: var(--color-paper, #ffffff);
  text-decoration: none;
  font-size: 1rem;
}
.ro-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--gradient-iridescent-fade));
  color: var(--color-paper, #ffffff);
  border-radius: var(--radius-buttons);
  text-decoration: none;
  font-weight: var(--font-weight-semibold);
  margin-top: auto;
}
@media (max-width: 768px) {
  .ro-header__nav { display: none; }
  .ro-header__toggle { display: flex; }
}

