import React, { useState } from 'react';
import './Testimonials.css';

interface Testimonial {
  id: string;
  quote: string;
  author: string;
  role: string;
  company: string;
  rating: number;
}

const TESTIMONIALS: Testimonial[] = [
  {
    id: '1',
    quote: 'Monopo Saigon transformed our digital brand from a conventional retail presence into an international cultural benchmark. Their precision and typography are second to none.',
    author: 'Kenji Takahashi',
    role: 'Creative Director',
    company: 'NeoTokyo Apparel',
    rating: 5,
  },
  {
    id: '2',
    quote: 'Uncompromising editorial elegance combined with high-velocity web performance. Our platform conversion increased by 42% in the first quarter post-launch.',
    author: 'Elena Rostova',
    role: 'Head of Brand Experience',
    company: 'Atelier Minimal',
    rating: 5,
  },
  {
    id: '3',
    quote: 'The Roobert design system created by the studio established a timeless identity. They do not just design websites; they curate living brand systems.',
    author: 'Duc Nguyen',
    role: 'Managing Partner',
    company: 'Saigon Architecture Collective',
    rating: 5,
  },
];

export function Testimonials() {
  const [activeIndex, setActiveIndex] = useState(0);

  const prev = () => setActiveIndex((idx) => (idx === 0 ? TESTIMONIALS.length - 1 : idx - 1));
  const next = () => setActiveIndex((idx) => (idx === TESTIMONIALS.length - 1 ? 0 : idx + 1));

  const current = TESTIMONIALS[activeIndex];

  return (
    <section className="ro-testimonials" id="testimonials" aria-label="Client Testimonials">
      <div className="ro-testimonials__inner">
        <div className="ro-testimonials__header">
          <p className="ro-testimonials__eyebrow">Client Endorsements</p>
          <h2 className="ro-testimonials__title">Words from Our Creative Partners</h2>
        </div>

        <div className="ro-testimonials__carousel">
          <div className="ro-testimonials__card">
            <div className="ro-testimonials__stars" aria-label={`Rating: ${current.rating} out of 5 stars`}>
              {Array.from({ length: current.rating }).map((_, i) => (
                <span key={i} className="ro-testimonials__star">★</span>
              ))}
            </div>

            <blockquote className="ro-testimonials__quote">
              “{current.quote}”
            </blockquote>

            <div className="ro-testimonials__meta">
              <div className="ro-testimonials__author-info">
                <span className="ro-testimonials__author">{current.author}</span>
                <span className="ro-testimonials__role">
                  {current.role} — <span className="ro-testimonials__company">{current.company}</span>
                </span>
              </div>

              <div className="ro-testimonials__nav">
                <button
                  type="button"
                  className="ro-testimonials__nav-btn"
                  onClick={prev}
                  aria-label="Previous testimonial"
                >
                  ←
                </button>
                <span className="ro-testimonials__counter">
                  0{activeIndex + 1} / 0{TESTIMONIALS.length}
                </span>
                <button
                  type="button"
                  className="ro-testimonials__nav-btn"
                  onClick={next}
                  aria-label="Next testimonial"
                >
                  →
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

